What does this do? package authz

default allow = false

allow {
 input.application = app
 appDefinition := data.applications[app]
 input.resource = res
 resourceDefinition := data.resources[app][res]
 allowedRights := getAzLocalRights(resourceDefinition.AzLocalRights, input.right)
 constraint := getConstraints(resourceDefinition.Constraints, allowedRights)
 userHasRight := input.right in getUserRights(data.resourceaccesses[app], input.user, input.resource)
 satisfiesConstraints := satisfiesConstraint(constraint, input.constraints)
 userHasRight
 satisfiesConstraints
}

getUserRights(resourceaccess, user, resource) = rights {
 rights = [r.AzLocalRightName | resourceaccess[user] != null;
 right := resourceaccess[user][resource];
 right != null;
 r := right[\_]
 ]
}

getAzLocalRights(azlocalrights, rightName) = rights {
 rights = [r | azlocalrights != null; r := azlocalrights[\_];
 r.AzLocalRightName == rightName
 ]
}

getConstraints(constraints, azlocalrights) = constraint {
 constraint = {
 k: v |
 azlocalrights != null;
 fieldType := [r |
 azlocalrights != null;
 r := azlocalrights[0].FieldTypes[\_];
 r.FieldType == k
 ][0]
 v := fieldType.FieldTypeValues[\_]
 }
}

satisfiesConstraint(constraints, input) {
 all(constraints, func(k, v) {
 input[k] == v
 })
}

